<style id="critical-home-styles">*,*::before,*::after{box-sizing:border-box}body.site-body{margin:0;font-family:var(--site-font-family,Inter,Arial,sans-serif);font-size:var(--site-base-size,16px);color:#eee;background:#03110c}body.site-body.home-body{color:#f4f1e9;background:#020a07}body.site-body a{color:inherit;text-decoration:none}body.site-body img{max-width:100%;display:block}.site-body .site-context-bar{position:absolute!important;width:1px!important;height:1px!important;margin:-1px!important;padding:0!important;overflow:hidden!important;clip:rect(0 0 0 0)!important;clip-path:inset(50%)!important;white-space:nowrap!important;border:0!important}html body.site-body.site-body[class] *:focus-visible{outline-width:2px!important;outline-style:solid!important;outline-color:var(--site-focus,#8cc63e)!important;outline-offset:3px!important}.home-body .home-page{color:#f4f1e9;background:#020a07}.btn{display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(90deg,#2e8a3f,#69a52d);color:#fff;padding:14px 24px;border:1px solid #6fa52f;border-radius:4px;font-weight:700;cursor:pointer}.btn.ghost{background:transparent;border-color:#aaa}.site-body .site-header[data-public-shell-region="header"]{position:relative;z-index:40;display:flex;width:100%;height:84px;min-height:84px;align-items:center;gap:16px;padding:0 24px;background:var(--layout-header-bg,#010705);border-bottom:1px solid rgba(96,137,73,.18);}.site-body .site-header[data-public-shell-region="header"] .brand{display:flex;width:232px;height:100%;flex:0 0 232px;align-items:center;justify-content:flex-start;}.site-body .site-header[data-public-shell-region="header"] .brand-logo-image{display:block;width:100%;height:68px;object-fit:contain;object-position:left center;}.site-body .site-header[data-public-shell-region="header"] .brand-logo-image--wide{object-fit:cover;object-position:left 34%;}.site-body .site-header[data-public-shell-region="header"] nav{display:flex;min-width:0;height:100%;a