-shell-region="header"] .brand-logo-image{width:166px;flex-basis:166px;}.site-body .site-header[data-public-shell-region="header"] .brand-logo-image{height:46px;}.site-body .site-header[data-public-shell-region="header"] .utilities{min-width:0;gap:4px;}.site-body .site-header[data-public-shell-region="header"] .utilities a{flex-basis:29px;min-width:29px;min-height:40px;}}@media (max-width:480px){.site-body .site-header[data-public-shell-region="header"]{height:62px;min-height:62px;gap:4px;padding:0 9px;}.site-body .site-header[data-public-shell-region="header"] .brand,.site-body .site-header[data-public-shell-region="header"] .brand-logo-image{width:132px;flex-basis:132px;}.site-body .site-header[data-public-shell-region="header"] .brand-logo-image{height:42px;}.site-body .site-header[data-public-shell-region="header"] .nav-toggle{width:34px;height:40px;}.site-body .site-header[data-public-shell-region="header"] .utilities{gap:2px;}.site-body .site-header[data-public-shell-region="header"] .utilities a{flex-basis:26px;min-width:26px;}}.home-page .home-hero--structured{position:relative;isolation:isolate;padding:clamp(34px,4.4vw,64px) clamp(18px,3.2vw,52px);overflow:hidden;background:radial-gradient(circle at 51% 40%,rgba(56,115,68,.22),transparent 27%),linear-gradient(105deg,#020a07 0%,#06190f 43%,#082519 72%,#04110b 100%);border-bottom:1px solid rgba(112,151,75,.34);}.home-page .home-hero--structured::before{position:absolute;z-index:-2;inset:0;background-image:var(--home-hero-background-image,none);background-position:center;background-size:cover;content:'';}.home-page .home-hero--structured.home-hero--has-video::before{background-image:none;}.home-page .home-hero-video-stage{position:absolute;z-index:-2;inset:0;display:grid;width:100%;height:100%;min-height:100%;overflow:hidden;background:#020a07;pointer-events:none;}.home-page .home-hero-video-stage--dual{grid-template-columns:1fr 1fr;}.home-page .home-hero-video-stage--single{grid-template-columns:1fr;}.home-page .home-hero-side-video{display:block;width:100%;height:100%;min-width:0;min-height:100%;object-fit:contain;object-position:center;background:#020a07;}.home-page .home-hero-video-stage--single .home-hero-side-video--right{object-position:right center;}.home-page .home-hero--structured::after{position:absolute;z-index:-1;inset:0;background:linear-gradient( 90deg,rgba(0,0,0,.82) 0%,rgba(0,0,0,.78) 12%,rgba(0,0,0,.62) 22%,rgba(0,0,0,.30) 32%,transparent 40%,transparent 66%,rgba(0,0,0,.22) 74%,rgba(0,0,0,.48) 82%,rgba(0,0,0,.72) 91%,rgba(0,0,0,.82) 100% );content:'';pointer-events:none;}.home-page .home-hero-structured-grid{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(360px,.88fr);align-items:stretch;gap:clamp(20px,2.6vw,40px);width:min(1460px,100%);min-height:clamp(430px,42vw,610px);margin:0 auto;}.home-page .home-hero-structured-copy{display:flex;min-width:0;flex-direction:column;justify-content:center;padding:12px 0;}.home-page .home-hero-structured-copy .eyebrow{margin:0;color:#97c63f;font-size:12px;font-weight:700;letter-spacing:.16em;}.home-page .home-hero-structured-copy h1{max-width:720px;margin:15px 0 18px;color:#f5f0e6;font-family:var(--site-heading-family,Georgia,serif);font-size:clamp(3rem,5.2vw,5.35rem);font-weight:500;line-height:.96;letter-spacing:-.025em;}.home-page .home-hero-structured-copy h1 span{display:block;}.home-page .home-hero-structured-copy h1 .home-hero-title-accent{color:#72bd35;}.home-page .home-hero-structured-intro{max-width:560px;margin:0;color:#ccd8d0;font-size:clamp(.94rem,1.15vw,1.08rem);line-height:1.68;}.home-page .home-hero-structured-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px;}.home-page .home-hero-structured-actions .btn{min-height:46px;padding-inline:20px;}.home-page .home-hero-structured-product{position:relative;min-width:0;min-height:430px;overflow:hidden;background:radial-gradient(circle at 50% 38%,rgba(87,153,84,.38),transparent 30%),linear-gradient(160deg,#153523,#06130d 70%);border:1px so